      icoQ: "lampQ",
      ask: "האם המנורה תידלק?",
      cantT: "אי אפשר להדליק",
      cantF: "אי אפשר לכבות",
      doubtT: "חושבים שאין שום דרך להדליק אותה?",
      doubtF: "חושבים שאין שום דרך לכבות אותה?",
      many: "דולקות",
      why: "למה המנורה במצב הזה",
      col: "עמודת המנורה",
      two: "שתי המנורות",
      same: "באותו מצב",
